impl<T: gx::Real> Vector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[3];
        let t3 = x[0].mul_add(x[0], t1);
        let t5 = (-t2).mul_add(T::from_i64(2), t3);
        t5
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (19 mul, 7 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Vector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[3];
        let t4 = t0 * t1;
        let t6 = t1 * t1;
        let t8 = t2 * t2;
        let t9 = t0.mul_add(t0, t6);
        let t11 = (-t0).mul_add(t2, t8);
        let t12 = (-t1).mul_add(t2, t11);
        let t14 = t4.mul_add(T::from_i64(2), t9);
        let t15 = t12.mul_add(T::from_i64(4), t14);
        let t16 = t15.recip();
        let t18 = t1 * t16;
        let t19 = t2 * t16;
        let t20 = t0.mul_add(t16, t18);
        let t22 = (-t19).mul_add(T::from_i64(2), t20);
        let t23 = x[0] * t22;
        let t24 = x[1] * t22;
        let t25 = x[2] * t22;
        let t26 = x[3] * t22;
        Vector::from_coeffs([t23, t24, t25, t26])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[3];
        let p3 = x[0].mul_add(x[0], p1);
        let p5 = (-p2).mul_add(T::from_i64(2), p3);
        let s0 = (p5).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Vector::from_coeffs([t0, t1, t2, t3]))
    }

}

impl<T: gx::Coef> gx::NewtonStep for Vector<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[3];
        let t3 = x[0].mul_add(x[0], t1);
        let t5 = (-t2).mul_add(T::from_i64(2), t3);
        let t7 = (-t5).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t8 = x[0] * t7;
        let t9 = x[1] * t7;
        let t10 = x[2] * t7;
        let t11 = x[3] * t7;
        let t12 = t8 * T::from_ratio(3, 2);
        let t13 = t9 * T::from_ratio(3, 2);
        let t14 = t10 * T::from_ratio(3, 2);
        let t15 = t11 * T::from_ratio(3, 2);
        Vector::from_coeffs([t12, t13, t14, t15])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

