    /// A value from its coefficients, in blade order.
    #[inline(always)]
    #[allow(clippy::too_many_arguments)]
    pub const fn new(e12: T, e1o: T, e2o: T, e1i: T, e2i: T, eoi: T) -> Self {
        Bivector { c: [e12, e1o, e2o, e1i, e2i, eoi] }
    }

    /// gx::Prepare this versor's action on kind `X` for applying it to many objects (see
    /// [`gx::Prepared`]).
    #[inline(always)]
    pub fn prepare<X>(self) -> <Self as gx::Prepare<X>>::Output
    where
        Self: gx::Prepare<X>,
    {
        gx::Prepare::prepare(self)
    }

    /// The identity map on `Bivector`: a `Bivector` with one open `Bivector` slot.
    #[inline(always)]
    pub fn slot() -> Bivector<(Bivector,), T> {
        Bivector { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `e12`.
    #[inline(always)]
    pub fn e12(&self) -> T {
        self.c[0]
    }

    /// Coefficient of `e1o`.
    #[inline(always)]
    pub fn e1o(&self) -> T {
        self.c[1]
    }

    /// Coefficient of `e2o`.
    #[inline(always)]
    pub fn e2o(&self) -> T {
        self.c[2]
    }

    /// Coefficient of `e1i`.
    #[inline(always)]
    pub fn e1i(&self) -> T {
        self.c[3]
    }

    /// Coefficient of `e2i`.
    #[inline(always)]
    pub fn e2i(&self) -> T {
        self.c[4]
    }

    /// Coefficient of `eoi`.
