        let t12 = t2.mul_add(T::from_ratio(1, 2), t10);
        let t13 = x[0] * x[7];
        let t14 = x[1] * x[6];
        let t15 = t13 - t14;
        let t16 = x[2] * x[5];
        let t17 = x[3] * x[4];
        let t18 = t16 - t17;
        let t19 = t13 + t18;
        let t21 = (-t14).mul_add(T::from_ratio(3, 2), t19);
        let t22 = t15 + t16;
        let t24 = (-t17).mul_add(T::from_i64(2), t22);
        let t25 = t18 - t14;
        let t27 = t25.mul_add(T::from_ratio(2, 3), t13);
        let t28 = t15 - t17;
        let t30 = t28.mul_add(T::from_ratio(1, 2), t16);
        let t31 = t0 - t3;
        let t32 = t31 - T::from_i64(3);
        let t34 = (-t12).mul_add(T::from_i64(2), t1);
        let t35 = t7 * T::from_ratio(1, 2);
        let t36 = t8 - t35;
        let t37 = t9 - t35;
        let t39 = x[0] * t34;
        let t42 = x[1] * x[2];
        let t44 = x[1] * x[3];
        let t45 = x[5] * t44;
        let t46 = x[1] * t32;
        let t49 = x[3] * t30;
        let t51 = x[3] * t37;
        let t52 = x[4] * t36;
        let t54 = x[4] * t30;
        let t57 = x[6] * t12;
        let t58 = x[6] * t32;
        let t60 = x[7] * t3;
