impl<T: gx::Real> gx::Log<Bivector<(), T>> for gx::Unit<Even<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Bivector<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p2 = x[3] * x[5];
        let p3 = x[6] * x[6];
        let p6 = x[3] * x[4];
        let p7 = (-x[1]).mul_add(x[1], p3);
        let p8 = x[2].mul_add(x[4], p2);
        let p10 = p8.mul_add(T::from_i64(2), p7);
        let p11 = x[1].mul_add(x[6], p6);
        let p12 = (-x[2]).mul_add(x[5], p11);
        let p13 = p12 * T::from_i64(2);
        let [h0, h1] = gx::study::log_coeffs(-1, (x[0], x[7]), (p10, p13));
        let t1 = x[6] * h1;
        let t2 = x[2] * h0;
        let t5 = x[3] * h0;
        let t7 = x[5] * h1;
        let t9 = x[5] * h0;
        let t11 = x[6] * h0;
        let t12 = x[1].mul_add(h0, t1);
        let t13 = (-x[3]).mul_add(h1, t2);
        let t14 = x[2].mul_add(h1, t5);
        let t15 = x[4].mul_add(h0, t7);
        let t16 = (-x[4]).mul_add(h1, t9);
        let t17 = (-x[1]).mul_add(h1, t11);
        Bivector::from_coeffs([t12, t13, t14, t15, t16, t17])
        })
    }
}

