        let t38 = t2.mul_add(t2, t36);
        let t39 = t37 + t38;
        let t40 = t0.mul_add(t1, t15);
        let t41 = t1.mul_add(t2, t40);
        let t42 = (-t0).mul_add(t2, t35);
        let t43 = (-t1).mul_add(t3, t42);
        let t44 = t41 + t43;
        let t46 = t4.mul_add(t4, t27);
        let t47 = t2.mul_add(t4, t46);
