        let t69 = t2 * t66;
        let t70 = t3 * t66;
        let t71 = t0.mul_add(t66, t68);
        let t72 = t69 + t70;
        let t73 = t71 - t72;
        let t75 = t5 * t66;
        let t76 = t4.mul_add(t66, t75);
        let t78 = t69.mul_add(T::from_ratio(1, 2), t76);
        let t79 = t6 * t66;
        let t80 = t7 * t66;
        let t81 = t79 - t80;
        let t82 = t8 * t66;
        let t84 = (-t9).mul_add(t66, t82);
