        let t148 = (-x[4]).mul_add(t73, t147);
        let t149 = (-x[3]).mul_add(t81, t123);
        let t150 = t149 * T::from_i64(2);
        let t151 = (-x[5]).mul_add(t73, t150);
        let t152 = (-t66).mul_add(t125, t128);
        let t154 = (-t127).mul_add(T::from_i64(2), t152);
        let t155 = x[0].mul_add(t90, t131);
        let t156 = (-x[1]).mul_add(t104, t155);
