#[doc = "A general multivector."]
///
/// Blades, in coefficient order: `[1, e1, e2, eo, ei, e12, e1o, e2o, e1i, e2i, eoi, e12o, e12i, e1oi, e2oi, e12oi]`.
///
/// `S` lists the open slots: `Multivector` (that is, `Multivector<()>`) is a value, `Multivector<(A,)>` a
/// linear map from `A`, `Multivector<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Multivector<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 16],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Multivector<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Multivector<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Multivector<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Multivector<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Multivector");
        for (b, c) in <Multivector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Multivector {
    const N: usize = 16;
    const NAME: &'static str = "Multivector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["1", "e1", "e2", "eo", "ei", "e12", "e1o", "e2o", "e1i", "e2i", "eoi", "e12o", "e12i", "e1oi", "e2oi", "e12oi"];
    type Arr<X: gx::Elem> = [X; 16];
    type Mv<S: gx::Slots, T: gx::Coef> = Multivector<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 16] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7), f(8), f(9), f(10), f(11), f(12), f(13), f(14), f(15)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 16], mut f: impl FnMut(&X) -> Y) -> [Y; 16] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7]), f(&a[8]), f(&a[9]), f(&a[10]), f(&a[11]), f(&a[12]), f(&a[13]), f(&a[14]), f(&a[15])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 16],
        b: &[Y; 16],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 16] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7]), f(&a[8], &b[8]), f(&a[9], &b[9]), f(&a[10], &b[10]), f(&a[11], &b[11]), f(&a[12], &b[12]), f(&a[13], &b[13]), f(&a[14], &b[14]), f(&a[15], &b[15])]
    }
}

